import org.springframework.stereotype.Service;

@Service
public class TransferServiceLegacy {
  private final AccountRepository accountRepo;

  public TransferServiceLegacy(AccountRepository accountRepo) {
    this.accountRepo = accountRepo;
  }

  // ❌ OLD: No transaction. Each repository call runs in its own
  // autocommit transaction: debit() commits immediately. If credit()
  // throws, the money has already left the 'from' account — money is
  // lost and the accounts are inconsistent. Partial writes are the
  // classic consequence of missing @Transactional.
  void transfer(String from, String to, int amount) {
    accountRepo.debit(from, amount); // ❌ OLD: committed already
    accountRepo.credit(to, amount); // ❌ OLD: failure leaves half-done state
  }
}

