import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class TransferService {
  private final AccountRepository accountRepo;

  public TransferService(AccountRepository accountRepo) {
    this.accountRepo = accountRepo;
  }

  // ✅ NEW: The whole method is one transaction. Spring opens a
  // transaction before the call and commits only if everything
  // succeeds; any RuntimeException rolls back both writes.
  @Transactional // ✅ NEW: atomic boundary
  void transfer(String from, String to, int amount) {
    accountRepo.debit(from, amount);
    accountRepo.credit(to, amount); // ✅ NEW: if this throws, debit rolls back
  }

  // For queries:
  @Transactional(readOnly = true) // ✅ NEW: hints a read-only transaction
  int balance(String account) {
    return accountRepo.balance(account);
  }
}
